  width: 40px;
  height: 40px;
  font-size: 1.2rem;
  cursor: pointer;
  transition: background 0.2s, transform 0.2s;
  display: flex;
  align-items: center;
  justify-content: center;
}

.theme-btn:hover {
  background: rgba(255,255,255,0.35);
  transform: rotate(20deg);
}

/* =============================================
   MIDDLE ROW
   ============================================= */
.middle-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

/* =============================================
   TIMER CARD
   ============================================= */
.card-timer {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
}

.timer-display {
  font-size: clamp(2.8rem, 6vw, 4.5rem);
  font-weight: 800;
  color: var(--timer-color);
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.04em;
  margin-bottom: 20px;
  line-height: 1;
}

.timer-controls {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
  justify-content: center;
}

/* =============================================
   TASKS CARD
   ============================================= */
.task-input-row {
  display: flex;
  gap: 8px;
  margin-bottom: 8px;
}

.task-input-row input {
  flex: 1;
  min-width: 0;
}

.task-error {
  font-size: 0.8rem;
  color: var(--error-color);
  margin-bottom: 8px;
  font-weight: 500;
}

.task-error.hidden {
  display: none;
}

.task-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
  max-height: 240px;
  overflow-y: auto;
  padding-right: 2px;
}

/* Custom scrollbar */
.task-list::-webkit-scrollbar {
  width: 5px;
}
.task-list::-webkit-scrollbar-track {
  background: var(--input-bg);
  border-radius: 4px;
}
.task-list::-webkit-scrollbar-thumb {
  background: var(--input-border);
  border-radius: 4px;
}

.task-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  background: var(--input-bg);
  border-radius: 10px;
  border: 1px solid var(--divider);
  transition: background 0.2s;
  animation: slideIn 0.2s ease;
}

@keyframes slideIn {
  from { opacity: 0; transform: translateY(-6px); }
  to   { opacity: 1; transform: translateY(0); }
}

.task-item input[type="checkbox"] {
  width: 17px;
  height: 17px;
  accent-color: var(--btn-primary-bg);
  cursor: pointer;
  flex-shrink: 0;
}

.task-label {
  flex: 1;
  font-size: 0.9rem;
  color: var(--text-primary);
  word-break: break-word;
  transition: color 0.2s, text-decoration 0.2s;
}

.task-label.done {
  text-decoration: line-through;
  color: var(--task-done-color);
}

.task-delete-btn {
  flex-shrink: 0;
  background: var(--btn-red-bg);
  color: #fff;
  border: none;
  border-radius: 7px;
  padding: 4px 9px;
  font-size: 0.75rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.2s;
}

.task-delete-btn:hover {
  background: var(--btn-red-hover);
}

/* =============================================
   QUICK LINKS CARD
   ============================================= */
.link-input-group {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin-bottom: 8px;
}

.link-input-group input {
  flex: 1;
  min-width: 120px;
}

.links-container {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  padding-top: 6px;
}

.link-pill {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  background: var(--pill-bg);
  color: #fff;
  padding: 7px 14px 7px 16px;
  border-radius: 50px;
  font-size: 0.87rem;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  transition: background 0.2s, transform 0.15s;
  animation: slideIn 0.2s ease;
}

.link-pill:hover {
  background: var(--pill-hover);
  transform: translateY(-2px);
}

.link-pill-text {
  text-decoration: none;
  color: inherit;
}

.link-pill-delete {
  background: rgba(255,255,255,0.30);
  border: none;
  color: #fff;
  border-radius: 50%;
  width: 18px;
  height: 18px;
  font-size: 0.75rem;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: background 0.2s;
  line-height: 1;
}

.link-pill-delete:hover {
  background: rgba(255,255,255,0.55);
}

/* =============================================
   SHARED INPUT STYLES
   ============================================= */
input[type="text"],
input[type="url"] {
  padding: 10px 14px;
  border: 2px solid var(--input-border);
  border-radius: 10px;
  font-size: 0.9rem;
  background: var(--input-bg);
  color: var(--text-primary);
  outline: none;
  transition: border-color 0.2s, background 0.3s;
  width: 100%;
}

input[type="text"]::placeholder,
input[type="url"]::placeholder {
  color: var(--text-muted);
}

input[type="text"]:focus,
input[type="url"]:focus {
  border-color: var(--input-focus);
  background: var(--card-bg);
}

/* =============================================
   BUTTONS — SHARED
   ============================================= */
.btn {
  padding: 10px 18px;
  border: none;
  border-radius: 10px;
  font-size: 0.9rem;
  font-weight: 600;
  cursor: pointer;
  white-space: nowrap;
  transition: background 0.2s, transform 0.1s, box-shadow 0.2s;
}

.btn:active {
  transform: scale(0.97);
}

.btn-primary {
  background: var(--btn-primary-bg);
  color: #fff;
}
.btn-primary:hover {
  background: var(--btn-primary-hover);
  box-shadow: 0 4px 14px rgba(110, 87, 229, 0.4);
}

.btn-green {
  background: var(--btn-green-bg);
  color: #fff;
}
.btn-green:hover {
  background: var(--btn-green-hover);
  box-shadow: 0 4px 14px rgba(62, 207, 142, 0.4);
}

.btn-yellow {
  background: var(--btn-yellow-bg);
  color: #fff;
}
.btn-yellow:hover {
  background: var(--btn-yellow-hover);
  box-shadow: 0 4px 14px rgba(245, 166, 35, 0.4);
}

.btn-red {
  background: var(--btn-red-bg);
  color: #fff;
}
.btn-red:hover {
  background: var(--btn-red-hover);
  box-shadow: 0 4px 14px rgba(224, 82, 82, 0.4);
}

/* =============================================
   RESPONSIVE
   ============================================= */
@media (max-width: 640px) {
  body {
    padding: 14px 10px 32px;
  }

  .card {
    padding: 20px 16px;
  }

  .middle-row {
    grid-template-columns: 1fr;
  }

  .task-input-row {
    flex-direction: column;
  }

  .task-input-row input {
    width: 100%;
  }

  .link-input-group {
    flex-direction: column;
  }

  .link-input-group input {
    min-width: unset;
    width: 100%;
  }

  .timer-controls {
    gap: 8px;
  }

  .btn {
    padding: 9px 14px;
    font-size: 0.85rem;
  }
}

@media (min-width: 641px) and (max-width: 800px) {
  .middle-row {
    grid-template-columns: 1fr 1fr;
  }
}

